import React, { useEffect, useState } from 'react';
import { SafeAreaView, Image, ImageBackground, FlatList, TouchableOpacity, View, Dimensions, Alert } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { useTheme, Text, BottomSheetManager, BottomSheet, SimpleHeader, LoadingBlockerView } from '@core/ui';
import type { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import useStyles from './style';
import PdfViewer from '../components/pdf/Pdf';
import ListOptions from '../components/list_options/ListOptions';
import ModalInput from '../components/modal_input/ModalInput';
import { ProductStatus } from './ProductStatus';
import { useDispatch, useSelector } from '@src/lib/redux';
import { fetchClientInfo } from '../loan_register/register_confirm/redux/thunk';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { selectClientInfo, selectClientType, selectError, selectFlow, selectStatus } from './selector';
import { ACCESS_TOKEN_INVALID, DIN } from '@src/utils/constants';
import BottomSheetSelectList from '../components/bottomSheetSelectList';
import DataSelectList from '../components/selectList/type';
import { useTranslation } from '@core/service';
import { LoanRegisterSlice } from '../loan_register/register_confirm/redux/slice';
import ProductSlice from './slice';
import getImg from '@src/utils/getImg';
const windowWidth = Dimensions.get('window').width;
const source = { uri: 'https://vikki-cdn.sit.galaxyfinx.cloud/term_and_condition/v0.0.1/TnC_Data.pdf', cache: true };

const ProductsScreen: React.FC = () => {
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { theme } = useTheme();
    const styles = useStyles();
    const { t } = useTranslation(['module_products']);


    const listOptionRegisterLoan = [
        { id: 1, title: `${t('screen_products.register_loan_for_personal')}`, fn: () => { dispatch(LoanRegisterSlice.actions.updateFlowRegister('personal')); navigation.navigate('register_confirm') } },
        { id: 2, title: `${t('screen_products.register_loan_for_other')}`, fn: () => { dispatch(LoanRegisterSlice.actions.updateFlowRegister('other')); navigation.navigate('register_confirm') } },
    ] as DataSelectList[];
    const [optionSelected, setOptionSelected] = useState<string>('');
    const [text, setText] = useState<any>();
    const clientInfo = useSelector(selectClientInfo);
    const status = useSelector(selectStatus);
    const error = useSelector(selectError);
    const clientType = useSelector(selectClientType);
    const [showListOptionRegisterLoan, setShowListOptionRegisterLoan] = useState<boolean>(false);
    const flow = useSelector(selectFlow);

    const handleCollateral = () => {
        dispatch(ProductSlice.actions.updateFlow('loan_collateral'));
        dispatch(fetchClientInfo({ clientNo: '00052339' } as GetClientInfoPayload['data']));
    };

    const data = [
        {
            id: '1',
            src: getImg('/assets/images/banner_1.png')
        },
        {
            id: '2',
            src: getImg('/assets/images/banner_2.png'),
        },
        {
            id: '3',
            src: getImg('/assets/images/banner_3.png'),
            onPress: handleCollateral,
        },
        {
            id: '4',
            src: getImg('/assets/images/banner_4.png'),
            onPress: () => {
                dispatch(LoanRegisterSlice.actions.updateFlowRegister('personal'));
                navigation.navigate('register_confirm');
                //setShowListOptionRegisterLoan(true)
            },
        },
    ];

    useEffect(() => {
        if (flow === 'loan_collateral' && clientType === DIN && error !== ACCESS_TOKEN_INVALID && status !== 'loading') {
            navigation.navigate('collateral_accounts');
        }
    }, [clientType]);

    if (status === 'failed') {
        Alert.alert('Thông báo', error || 'Lỗi hệ thống');
    }

    return (
        <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={{ flex: 1 }}>
            <SafeAreaView style={styles.wrapper}>
                <SimpleHeader allowGoBack title='Đăng ký vay' />
                <Text style={styles.title}>Chọn loại hình vay</Text>
                <FlatList
                    data={data}
                    renderItem={({ item, index }) => (
                        <TouchableOpacity key={item?.id} onPress={item?.onPress}>
                            <Image
                                source={item?.src}
                                style={[
                                    styles.bannerItem,
                                    {
                                        marginTop: index > 0 ? theme.Size.Horizontal.Medium : 0,
                                    },
                                ]}
                            />
                        </TouchableOpacity>
                    )}
                    keyExtractor={(item) => item.id}
                    style={styles.bannerList}
                />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
            </SafeAreaView>
            <BottomSheetSelectList title={t('screen_products.title_list_options_register_loan')} show={showListOptionRegisterLoan} listSelect={listOptionRegisterLoan} onClose={() => setShowListOptionRegisterLoan(false)} />
        </ImageBackground>
    );
};

export default ProductsScreen;
