import { FormInput, Spacer, GradientButton, MaterialTextInput, INPUT_STATUS, Text, useTheme, useKeyboard } from '@core/ui';
import React, { FC, useEffect, useState } from 'react';
import useCSS from '@src/presentation/style';
import { formatMoney } from '@src/utils/currency';
import { InputModeOptions, Keyboard, SafeAreaView } from 'react-native';
import { ValidationResult } from '@src/utils/validator';
import { useTranslation } from '@core/service';
interface Props {
    value: string;
    onSubmit: (text: string) => void;
    placeholder?: string;
    label?: string;
    inputType?: string;
    format?: string;
    validate?: (value: string) => ValidationResult;
}

const ContentInput: FC<Props> = ({ value, onSubmit, placeholder, label, inputType = 'default', format, validate, ...props }) => {
    const css = useCSS();
    const { theme } = useTheme();
    const [displayValue, setDisplayValue] = useState(value);
    const [errorMessages, setErrorMessages] = useState<string | undefined>();
    const { t } = useTranslation(['validator']);
    const { keyboardState } = useKeyboard();
    const handleInputWithFormat = (text: string) => {
        let value = text;
        switch (format) {
            case 'money':
                value = formatMoney(text?.replaceAll(',', '') ?? '');
                break;
            default:
                break;
        }
        setDisplayValue(value);
    };
    const handleValidate = (value: string) => {
        const validation = validate?.(value);
        if (validation?.isEmpty) {
            setErrorMessages(validation.errors);
            return false;
        }
        if (validation?.isInvalid) {
            setErrorMessages(validation?.errors);
            return false;
        }
        return true;
    };
    const handleSubmit = () => {
        const isValid = handleValidate(displayValue);
        if (!isValid) {
            return;
        }
        let submitValue = displayValue;
        switch (format) {
            case 'money':
                submitValue = displayValue?.replaceAll?.(',', '');
                break;
            default:
                break;
        }
        onSubmit?.(submitValue);
        Keyboard.dismiss();
    }
    useEffect(() => {
        const isValid = handleValidate(displayValue);
        if (isValid) {
            setErrorMessages('');
        }
    }, [displayValue]);
    return (
        <SafeAreaView>
            <Spacer height={16} />
            <MaterialTextInput
                label={label}
                placeholder={placeholder}
                // keyboardType={inputType}
                value={displayValue}
                onChangeText={handleInputWithFormat}
                autoFocus={false}
                inputMode={inputType as InputModeOptions || 'text'}
                {...props}
            />
            <Text style={{ ...theme.Typography.TextCaption100.Regular, color: theme.Colors.Text.Error }}>{t(`${errorMessages}`)}</Text>
            <Spacer height={56} />
            <GradientButton gradientProps={{ type: 'primary' }} title='Lưu' onPress={handleSubmit} />
            <Spacer height={8} />
        </SafeAreaView>
    );
};
export default ContentInput;
