import { FormInput, Text, useTheme } from '@core/ui';
import React, { useState } from 'react';
import useCSS from '@src/presentation/style';
import { View } from 'react-native';
import { TextInput } from 'react-native-gesture-handler';
import { CURRENCY } from '@src/utils/constants';

interface Props {
    value: number;
    onValueChange: (value: number) => void;
    currency?: string;
}

const CurrencyInput: React.FC<Props> = ({ value, onValueChange, currency = CURRENCY, ...props }) => {
    const css = useCSS();
    const { theme } = useTheme();

    const formatCurrency = (num: number) => {
        return num.toLocaleString('en-US');
    };
    const [displayValue, setDisplayValue] = useState(formatCurrency(value));
    const [isFocus, setIsFocus] = useState(false);
    const handleChange = (text: string) => {
        const numericValue = Number(text.replace(/\D/g, '')); // Lọc bỏ ký tự không phải số
        setDisplayValue(formatCurrency(numericValue));
        onValueChange(numericValue);
    };
    return (
        <View style={[css.pb_small, css.border_b_1, isFocus ? css.border_b_orange_600 : css.border_b_neutral_300]}>
            <View style={[css.row, css.justify_center, css.items_end]}>
                <View style={[{ height: theme.Size.vs(42) }]}>
                    <TextInput
                        keyboardType='number-pad'
                        autoFocus
                        value={displayValue}
                        onChangeText={handleChange}
                        onFocus={() => setIsFocus(true)}
                        onBlur={() => setIsFocus(false)}
                        placeholder={'0'}
                        placeholderTextColor={theme.Colors.Border.Neutral400}
                        selectionColor={theme.Colors.Main.Orange}
                        style={[css.text_center, css.font_semibold, css.text_large_title]}
                        {...props}
                    />
                </View>
                <Text style={[css.ml_small, css.mb_small, css.text_subheadline]}>{currency}</Text>
            </View>
        </View>
    );
};

export default CurrencyInput;
