import { ActionButton, createStyles, GradientButton, LinearProgressBar, LoadingBlockerView, Theme, useTheme } from '@core/ui';
import React, { ReactNode, useEffect, useState } from 'react';
import { Image, ImageBackground, SafeAreaView, ScrollView, TouchableOpacity, View } from 'react-native';
import { Text, CheckBox } from '@core/ui';
import useCSS from '@src/presentation/style';
import { SectionField, sectionFieldProps } from './components/sectionField';
import { useSelector } from 'react-redux';
import { selectBranchSelected, selectClientInfo, selectCmsLoanRegisterConfig, selectCmsLoanRegisterTnC, selectCmsStaticData, selectCmsStaticLoanCollateral, selectCmsStaticLoanGender, selectCmsStaticLoanMethod, selectCmsStaticLoanPurpose, selectFlowRegister, selectLoanDemandData, selectLoanDemandResponse, selectStatus } from './redux/selector';
import { useDispatch } from '@src/lib/redux';
import { confirmLoanRegister, fetchClientInfo, fetchCmsLoanRegisterConfig, fetchCmsLoanRegisterTnC, fetchCmsRegisterStaticData } from './redux/thunk';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { formatDate, useTranslation } from '@core/service';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import BottomSheetRadioList from '@src/presentation/components/bottomSheetRadioList';
import BottomSheetInput from '@src/presentation/components/bottomSheetInput';
import { registerStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';
import { LoanRegisterSlice } from './redux/slice';
import { RegisterLoanDemandPayload } from '@src/domain/entities/loan_register/loanDemand';
import { formatMoney, toText, toTextRound } from '@src/utils/currency';
import BottomSheetPDF from '@src/presentation/components/bottomSheetPDF';
import { CURRENCY } from '@src/utils/constants';
import BottomSheetBranch from '@src/presentation/components/bottomSheetBranch';
import { IBranch } from '@src/domain/entities/common/branch';
import BottomSheetSlider from '@src/presentation/components/bottomSheetSlider';
import { validator } from '@src/utils/validator';
import { selectBranches } from '@src/presentation/loan_collateral/collateral_confirm/selector';
import BottomSheetInputNameAndDob from './components/bsInputNameAndDob';
import getImg from '@src/utils/getImg';

interface ListOptionProps {
    id: number;
    content: string;
    type: string;
    code: string;
    selected?: boolean;
}
// type SectionProps = {
//     id?: string;
//     title: string;
//     render: ReactNode;
//     divider: boolean;
//     fn?: () => void;
//     isRequired?: boolean;
// }
export class Query<TParameter> {
    query: TParameter;

    constructor(params: { query: TParameter }) {
        this.query = params.query;
    }
}

const RegisterConfirmScreen = () => {
    const styles = useStyles();
    const css = useCSS();
    const { theme } = useTheme();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_register']);

    const status = useSelector(selectStatus);
    const clientInfo = useSelector(selectClientInfo);
    const cmsStaticData = useSelector(selectCmsStaticData);
    const { globalId, phoneNumber, emailAddress, sex, consultantId, loanAmount, monthlyIncome, loanPurpose, collateral, loanMethod, repaymentMethod, branchId, loanTerm, expectedInterestRate, address, clientNo } = useSelector(selectLoanDemandData);
    const cmsLoanRegisterConfig = useSelector(selectCmsLoanRegisterConfig);
    const cmsLoanRegisterTnC = useSelector(selectCmsLoanRegisterTnC);
    const branchList = useSelector(selectBranches);
    const branchSelected = useSelector(selectBranchSelected);
    const registerLoanDemandResponse = useSelector(selectLoanDemandResponse);
    const flowRegister = useSelector(selectFlowRegister);

    const [showBottomSheetOptionsPurpose, setShowBottomSheetOptionsPurpose] = useState(false);
    const [showBottomSheetOptionsCollateral, setShowBottomSheetOptionsCollateral] = useState(false);
    const [showBottomSheetOptionsLoanType, setShowBottomSheetOptionsLoanType] = useState(false);
    const [showBottomSheetOptionsGender, setShowBottomSheetOptionsGender] = useState(false);
    const [showBottomSheetInputPhoneNumber, setShowBottomSheetInputPhoneNumber] = useState(false);
    const [showBottomSheetInputEmail, setShowBottomSheetInputEmail] = useState(false);
    const [showBottomSheetInputHDCode, setShowBottomSheetInputHDCode] = useState(false);
    const [showBottomSheetInputTotalIncome, setShowBottomSheetInputTotalIncome] = useState(false);
    const [showBottomSheetPDF, setShowBottomSheetPDF] = useState(false);
    const [showBottomSheetInputLoanAmount, setShowBottomSheetInputLoanAmount] = useState(false);
    const [showBottomSheetSliderLoanTerm, setShowBottomSheetSliderLoanTerm] = useState(false);
    const [showBottomSheetListBranch, setShowBottomSheetListBranch] = useState(false);
    const [showBottomSheetloanTerm, setShowBottomSheetloanTerm] = useState(false);
    const [monthlyRepayment, setMonthlyRepayment] = useState(0);
    const [isTickTnC, setIsTickTnC] = useState(true);
    const [listEmpty, setListEmpty] = useState<Record<string, boolean>>({});
    const [showBottomSheetInputNameAndDob, setShowBottomSheetInputNameAndDob] = useState(false);

    const textAction = () => {
        return <Text style={{ ...theme.Typography.TextSubheadline.SemiBold, color: theme.Colors.Text.Neutral500 }}>{t('screen_confirm.action_input_title')}</Text>
    }
    //#region section data
    const infoSection: sectionFieldProps[] = [
        {
            id: 'globalId',
            title: t('screen_confirm.customer_info.globalId'),
            divider: false,
            isRequired: true,
            value: globalId
        },
        {
            id: 'phoneNumber',
            title: t('screen_confirm.customer_info.phone'),
            divider: true,
            fn: () => { setShowBottomSheetInputPhoneNumber(true) },
            isRequired: true,
            value: phoneNumber,
            showArrow: true
        },
        {
            id: 'emailAddress',
            title: t('screen_confirm.customer_info.email'),
            divider: true,
            fn: () => {
                setShowBottomSheetInputEmail(true);
            },
            value: emailAddress,
            showArrow: true
        },
        {
            id: 'sex',
            title: t('screen_confirm.customer_info.gender'),
            divider: true,
            fn: () => { setShowBottomSheetOptionsGender(true) },
            isRequired: true,
            value: sex ? (sex === 'M' ? t('screen_confirm.customer_info.male') : t('screen_confirm.customer_info.female')) : '',
            showArrow: true
        },
        {
            id: 'address',
            title: t('screen_confirm.customer_info.address'),
            divider: true,
            isRequired: true,
            value: address
        }
    ]
    const introduceSection: sectionFieldProps[] = [
        {
            title: t('screen_confirm.introduce_info.HDCode'),
            divider: false,
            fn: () => {
                setShowBottomSheetInputHDCode(true);
            },
            value: consultantId,
            showArrow: true
        },
        {
            id: 'branchId',
            title: t('screen_confirm.introduce_info.branch'),
            divider: true,
            fn: () => { setShowBottomSheetListBranch(true) },
            isRequired: true,
            value: branchSelected?.branchName,
            showArrow: true
        }
    ]
    const loanInfoSection: sectionFieldProps[] = [
        {
            id: 'loan_term',
            title: t('screen_confirm.loan_info.loan_term'),
            divider: false,
            fn: () => { setShowBottomSheetSliderLoanTerm(true) },
            isRequired: true,
            value: `${String(loanTerm) || cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanTerm?.[0]?.loan_term_default} ${t('screen_confirm.loan_info.unit_year')}`,
            showArrow: true
        },
        {
            id: 'expectedInterestRate',
            title: t('screen_confirm.loan_info.expected_interest_rate'),
            divider: true,
            isRequired: true,
            value: expectedInterestRate ? `${expectedInterestRate} %` : ''
        },
        {
            id: 'monthlyRepayment',
            title: t('screen_confirm.loan_info.monthly_repayment'),
            divider: true,
            isRequired: true,
            value: monthlyRepayment ? (formatMoney(monthlyRepayment) + ' ' + CURRENCY) : ''
        },
        {
            id: 'monthlyIncome',
            title: t('screen_confirm.loan_info.monthly_income'),
            divider: true,
            fn: () => { setShowBottomSheetInputTotalIncome(true) },
            isRequired: true,
            value: monthlyIncome ? (formatMoney(monthlyIncome) + ' ' + CURRENCY) : '',
            showArrow: true
        }
    ]
    const loanDetailSection: sectionFieldProps[] = [
        {
            id: 'loanPurpose',
            title: t('screen_confirm.loan_detail.loan_purpose'),
            divider: false,
            fn: () => { setShowBottomSheetOptionsPurpose(true) },
            isRequired: true,
            value: loanPurpose,
            showArrow: true
        },
        {
            id: 'collateral',
            title: t('screen_confirm.loan_detail.loan_collateral'),
            divider: true,
            fn: () => { setShowBottomSheetOptionsCollateral(true) },
            isRequired: true,
            value: collateral,
            showArrow: true
        },
        {
            id: 'loanMethod',
            title: t('screen_confirm.loan_detail.loan_method'),
            divider: true,
            fn: () => { setShowBottomSheetOptionsLoanType(true) },
            isRequired: true,
            value: loanMethod,
            showArrow: true
        },
        {
            id: 'repaymentMethod',
            title: t('screen_confirm.loan_detail.loan_repayment_method'),
            divider: true,
            isRequired: true,
            value: repaymentMethod
        },
    ];
    //#endregion

    //#region bottom sheet data
    const cmsStaticLoanPurpose = useSelector(selectCmsStaticLoanPurpose);
    const cmsStaticLoanMethod = useSelector(selectCmsStaticLoanMethod);
    const cmsStaticLoanCollateral = useSelector(selectCmsStaticLoanCollateral);
    const cmsStaticLoanGender = useSelector(selectCmsStaticLoanGender);

    const handleSelectPurpose = (data: registerStaticData) => {
        dispatch(LoanRegisterSlice.actions.selectCmsStaticLoanPurpose(data));
    };
    const handleSelectCollateral = (data: registerStaticData) => {
        dispatch(LoanRegisterSlice.actions.selectCmsStaticLoanCollateral(data));
    };
    const handleSelectMethod = (data: registerStaticData) => {
        dispatch(LoanRegisterSlice.actions.selectCmsStaticLoanMethod(data));
    };
    const handleSelectGender = (data: registerStaticData) => {
        dispatch(LoanRegisterSlice.actions.selectCmsStaticLoanGender(data));
    };
    //#endregion

    const handleUpdateLoanDemandData = (data: Record<string, string>) => {
        // setPhoneNumber(data.phoneNumber || '');
        dispatch(LoanRegisterSlice.actions.updateLoanDemandData(data));
    };

    const handleConfirmRegister = () => {
        if (!isTickTnC) {
            return
        }
        const payload = { globalId, phoneNumber, emailAddress, sex, consultantId, loanAmount: Number(loanAmount), monthlyIncome: Number(monthlyIncome), loanPurpose, collateral, loanMethod, repaymentMethod, branchId, loanTerm: Number(loanTerm), expectedInterestRate: Number(expectedInterestRate), address, clientNo }
        const keys = Object.keys(payload);
        const empty: Record<string, boolean> = {};
        for (let i = 0; i < keys.length; i++) {
            let key = keys[i] as keyof typeof payload
            if (key === 'consultantId' || key === 'emailAddress') {
                continue;
            }
            if (!payload[key]) {
                empty[key] = true;
            }
        }
        setListEmpty(empty)
        console.log('empty', empty);
        if (Object.keys(empty).length > 0) {
            return;
        }
        dispatch(confirmLoanRegister(payload as RegisterLoanDemandPayload["data"]))
    }
    const handleSelectBranch = (branch: IBranch) => {
        dispatch(LoanRegisterSlice.actions.selectBranch(branch));
    }


    useEffect(() => {
        if (flowRegister === 'personal') {
            dispatch(fetchClientInfo({ clientNo: '20003036' } as GetClientInfoPayload['data']))
        }
        dispatch(fetchCmsRegisterStaticData('*'))
        dispatch(fetchCmsLoanRegisterConfig('*'))
        dispatch(fetchCmsLoanRegisterTnC('*'))
    }, [])

    useEffect(() => {
        // (Số tiền bạn muốn vay / (Thời gian vay * 12)) +(Số tiền bạn muốn vay * (Lãi suất dự kiến / 12))
        const payment = (loanAmount / ((+(loanTerm || 15)) * 12)) + (loanAmount * (cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_InterestRate?.[0]?.rate_value || 0) / 12);
        setMonthlyRepayment(Math.round(payment));
    }, [loanAmount])

    useEffect(() => {
        if (registerLoanDemandResponse?.resultCode === '00') {
            navigation.navigate('register_result');
        }
    }, [registerLoanDemandResponse])
    const start = 1900;
    const values = new Array(new Date().getFullYear() - start + 1)
        .fill(0)
        .map((_, i) => {
            const value = start + i;
            return { value, label: `${value}` };
        })
        .reverse();
    const defaultValue = 1990 - start;
    return (
        <ImageBackground source={getImg('/assets/images/bg/bg_body.jpg')} resizeMode='cover'>
            <SafeAreaView>
                {status === 'loading' && <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />}
                <ScrollView>
                    <View style={[css.ph_medium, css.pb_xxLarge, { flex: 1 }]}>
                        {/* <Picker {...{ values, defaultValue }} /> */}
                        <View style={[css.mt_medium]}>
                            <Text style={styles.title}>{t('screen_confirm.title')}</Text>
                        </View>
                        {/* section customer info */}
                        <View>
                            <View style={styles.sectionWrapper}>
                                <ImageBackground source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')} imageStyle={[css.rounded_tl_base, css.rounded_tr_base]}>
                                    <View style={[css.flex_1, css.row, css.items_center, css.mt_medium, css.pb_regular]}>
                                        <Image source={getImg('/assets/images/icons/default_avatar.png')} style={[css.ml_medium, css.mr_regular]} />
                                        <View style={[css.flex_1, css.row, css.items_center, css.justify_between, css.w_100pc]}>
                                            <View>
                                                <Text style={theme.Typography.TextSubheadline.Regular}>{t('screen_confirm.customer_info.name')}</Text>
                                                {flowRegister === 'personal' ?
                                                    <View>
                                                        <Text style={theme.Typography.Title200.Semibold}>{clientInfo?.data.clientName}</Text>
                                                        <Text style={theme.Typography.TextBody.Regular}>{t('screen_confirm.customer_info.dob')} {clientInfo?.data.birthDate && formatDate(clientInfo?.data.birthDate || '')}</Text>
                                                    </View>
                                                    :
                                                    <View>
                                                        <Text style={theme.Typography.Title200.Semibold}>{t('screen_confirm.customer_info.title_input_name_other')}</Text>
                                                    </View>
                                                }
                                            </View>
                                            {flowRegister === 'other' &&
                                                <View>
                                                    <TouchableOpacity onPress={() => { setShowBottomSheetInputNameAndDob(true) }}>
                                                        <Image source={getImg('/assets/images/icons/icon_edit.png')} style={{ width: theme.Size.Horizontal.xLarge, height: theme.Size.Vertical.xLarge, marginHorizontal: theme.Size.Horizontal.Regular }} />
                                                    </TouchableOpacity>
                                                </View>
                                            }
                                        </View>
                                    </View>
                                </ImageBackground>
                                <View style={[css.pv_medium]}>
                                    {infoSection.map((item, index) => (
                                        <SectionField key={index} title={item.title} render={item.render} divider={item.divider} fn={item?.fn} isRequired={item?.isRequired && !!listEmpty[(item?.id || '')]} value={item?.value} showArrow={item?.showArrow} />
                                    ))}
                                </View>
                            </View>
                            <View style={[css.pv_medium, { ...styles.sectionWrapper }]}>
                                {introduceSection.map((item, index) => (
                                    <SectionField key={index} title={item.title} render={item.render} divider={item.divider} fn={item?.fn} isRequired={item?.isRequired && !!listEmpty[(item?.id || '')]} value={item?.value} showArrow={item?.showArrow} />
                                ))}
                            </View>
                        </View>

                        {/* section loan info */}
                        <View>
                            <View style={styles.sectionWrapper}>
                                <ImageBackground
                                    source={getImg('/assets/images/bg/bg_header_Loan_registration_card.png')}
                                    imageStyle={[css.rounded_tl_base, css.rounded_tr_base]}>
                                    <View style={[css.row, css.items_center, css.mt_medium, css.pb_regular]}>
                                        <Image source={getImg('/assets/images/icons/icon_money.png')} style={[css.ml_medium, css.mr_regular]} />
                                        <View style={[css.flex_1]}>
                                            <TouchableOpacity activeOpacity={1}>
                                                <View style={[css.row, css.items_center, css.justify_between, css.w_100pc]}>
                                                    <View>
                                                        <Text style={theme.Typography.TextSubheadline.Regular}>{t('screen_confirm.loan_info.loan_amount')}</Text>
                                                        <Text style={theme.Typography.Title300.SemiBold}>{toTextRound.convert(loanAmount || cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanLimit?.[0]?.loan_limit_default)} {CURRENCY}</Text>
                                                    </View>
                                                    <View>
                                                        <TouchableOpacity
                                                            onPress={() => {
                                                                setShowBottomSheetInputLoanAmount(true);
                                                            }}>
                                                            <Image
                                                                source={getImg('/assets/images/icons/icon_edit.png')}
                                                                style={{
                                                                    width: theme.Size.Horizontal.xLarge,
                                                                    height: theme.Size.Vertical.xLarge,
                                                                    marginHorizontal: theme.Size.Horizontal.Regular,
                                                                }}
                                                            />
                                                        </TouchableOpacity>
                                                    </View>
                                                </View>
                                            </TouchableOpacity>
                                        </View>
                                    </View>
                                </ImageBackground>
                                <View style={[css.pv_medium]}>
                                    {loanInfoSection.map((item, index) => (
                                        <SectionField key={index} title={item.title} render={item.render} divider={item.divider} fn={item?.fn} isRequired={item?.isRequired && !!listEmpty[(item?.id || '')]} value={item?.value} showArrow={item?.showArrow} />
                                    ))}
                                </View>
                            </View>
                            <View style={[css.pv_medium, { ...styles.sectionWrapper }]}>
                                {loanDetailSection.map((item, index) => (
                                    <SectionField key={index} title={item.title} render={item.render} divider={item.divider} fn={item?.fn} isRequired={item?.isRequired && !!listEmpty[(item?.id || '')]} value={item?.value} showArrow={item?.showArrow} />
                                ))}
                            </View>
                        </View>

                        {/* section TnC */}
                        <View style={[css.pt_medium, css.row, css.justify_around]}>
                            <CheckBox title='' checked={isTickTnC} onPress={() => { setIsTickTnC(!isTickTnC); }} size='small' />
                            <Text style={{ ...theme.Typography.TextSubheadline.Regular, flex: 1 }}>{t('screen_confirm.tnc_prefix')} <Text style={{ ...theme.Typography.TextSubheadline.Underline, color: theme.Colors.Text.Error, fontWeight: theme.FontWeight.bold }} onPress={() => { setShowBottomSheetPDF(true) }}> Điều khoản, điều kiện </Text> {t('screen_confirm.tnc_suffix')}</Text>
                        </View>
                        <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_confirm.submit')} onPress={handleConfirmRegister} style={{ marginTop: theme.Size.Vertical.Medium }} />
                    </View>
                </ScrollView>

                {/* section component */}
                <View>
                    <BottomSheetRadioList
                        show={showBottomSheetOptionsPurpose}
                        title={t('screen_confirm.loan_detail.loan_purpose')}
                        listOption={cmsStaticLoanPurpose}
                        onClose={() => { setShowBottomSheetOptionsPurpose(false) }}
                        onSelected={(data) => {
                            handleSelectPurpose(data)
                            setListEmpty(() => {
                                delete listEmpty['loanPurpose'];
                                return listEmpty
                            })
                        }} />
                    <BottomSheetRadioList
                        show={showBottomSheetOptionsCollateral}
                        title={t('screen_confirm.loan_detail.loan_collateral')}
                        listOption={cmsStaticLoanCollateral}
                        onClose={() => { setShowBottomSheetOptionsCollateral(false) }}
                        onSelected={(data) => {
                            handleSelectCollateral(data)
                            setListEmpty(() => {
                                delete listEmpty['collateral'];
                                return listEmpty
                            })
                        }} />
                    <BottomSheetRadioList
                        show={showBottomSheetOptionsLoanType}
                        title={t('screen_confirm.loan_detail.loan_method')}
                        listOption={cmsStaticLoanMethod}
                        onClose={() => { setShowBottomSheetOptionsLoanType(false) }}
                        onSelected={(data) => {
                            handleSelectMethod(data)
                            setListEmpty(() => {
                                delete listEmpty['loanMethod'];
                                return listEmpty
                            })
                        }} />
                    <BottomSheetRadioList
                        show={showBottomSheetOptionsGender}
                        title={t('screen_confirm.customer_info.gender')}
                        listOption={cmsStaticLoanGender}
                        onClose={() => { setShowBottomSheetOptionsGender(false) }}
                        onSelected={(data) => {
                            handleSelectGender(data)
                            setListEmpty(() => {
                                delete listEmpty['sex'];
                                return listEmpty
                            })
                        }} />
                    <BottomSheetInput
                        title={t('screen_confirm.customer_info.phone')}
                        label={t('screen_confirm.customer_info.label_input_phone')}
                        labelSubmit={t('screen_confirm.customer_info.label_submit')}
                        inputType='numeric'
                        show={showBottomSheetInputPhoneNumber}
                        onClose={() => { setShowBottomSheetInputPhoneNumber(false) }}
                        onSubmit={(value: string) => {
                            setShowBottomSheetInputPhoneNumber(false);
                            handleUpdateLoanDemandData({ phoneNumber: value });
                            setListEmpty(() => { delete listEmpty['phoneNumber']; return listEmpty })
                        }}
                        textInputProps={
                            {
                                value: phoneNumber,
                                onChangeText: (value) => { },
                                placeholder: ''
                            }
                        }
                        validate={validator.validatePhoneNumber}
                    />
                    <BottomSheetInput
                        title={t('screen_confirm.customer_info.label_input_email')}
                        label={t('screen_confirm.customer_info.label_input_email')}
                        labelSubmit={t('screen_confirm.customer_info.label_submit')}
                        inputType='email'
                        show={showBottomSheetInputEmail}
                        onClose={() => { setShowBottomSheetInputEmail(false) }}
                        onSubmit={(value) => {
                            setShowBottomSheetInputEmail(false);
                            handleUpdateLoanDemandData({ emailAddress: value });
                            setListEmpty(() => { delete listEmpty['emailAddress']; return listEmpty })
                        }}
                        textInputProps={
                            {
                                value: emailAddress || '',
                                onChangeText: () => { },
                                placeholder: ''
                            }
                        }
                        validate={validator.validateEmail}
                    />
                    <BottomSheetInput
                        title={t('screen_confirm.introduce_info.HDCode')}
                        label={t('screen_confirm.introduce_info.label_input_HDCode')}
                        labelSubmit={t('screen_confirm.introduce_info.label_submit')}
                        show={showBottomSheetInputHDCode}
                        onClose={() => { setShowBottomSheetInputHDCode(false) }}
                        onSubmit={(value) => {
                            setShowBottomSheetInputHDCode(false);
                            handleUpdateLoanDemandData({ consultantId: value });
                            setListEmpty(() => {
                                delete listEmpty['consultantId'];
                                return listEmpty
                            })
                        }}
                        textInputProps={
                            {
                                value: consultantId || '',
                                onChangeText: () => { },
                                // placeholder: 'Nhập mã giới thiệu'
                            }
                        }
                        validate={validator.validateHDCode}
                    />
                    <BottomSheetPDF
                        show={showBottomSheetPDF}
                        title={t('screen_confirm.tnc_title')}
                        onClose={() => { setShowBottomSheetPDF(false) }}
                        link={cmsLoanRegisterTnC?.attributes?.pdf_file.data?.[0]?.attributes?.url || ''}
                    />
                    <BottomSheetInput
                        title={t('screen_confirm.loan_info.loan_amount')}
                        label={t('screen_confirm.loan_info.label_input_loan_amount')}
                        labelSubmit={t('screen_confirm.loan_info.label_submit')}
                        show={showBottomSheetInputLoanAmount}
                        onClose={() => { setShowBottomSheetInputLoanAmount(false) }}
                        onSubmit={(value) => {
                            setShowBottomSheetInputLoanAmount(false);
                            handleUpdateLoanDemandData({ loanAmount: value })
                            setListEmpty(() => {
                                delete listEmpty['numeric'];
                                return listEmpty
                            })
                        }}
                        inputType='numeric'
                        textInputProps={
                            {
                                value: formatMoney(loanAmount || cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanLimit?.[0]?.loan_limit_default) || '',
                                onChangeText: () => { },
                                placeholder: ''
                            }
                        }
                        format={'money'}
                        validate={(value) => validator.validateCurrency(value, Number(cmsLoanRegisterConfig?.data.attributes.DL_LoanRegister_LoanLimit?.[0].loan_limit_min), Number(cmsLoanRegisterConfig?.data.attributes.DL_LoanRegister_LoanLimit?.[0].loan_limit_max))}
                    />
                    <BottomSheetInput
                        title={t('screen_confirm.loan_info.label_input_monthly_income')}
                        label={t('screen_confirm.loan_info.label_input_monthly_income')}
                        labelSubmit={t('screen_confirm.loan_info.label_submit')}
                        inputType='numeric'
                        show={showBottomSheetInputTotalIncome}
                        onClose={() => { setShowBottomSheetInputTotalIncome(false) }}
                        onSubmit={(value) => {
                            setShowBottomSheetInputTotalIncome(false);
                            handleUpdateLoanDemandData({ monthlyIncome: value })
                            setListEmpty(() => {
                                delete listEmpty['monthlyIncome'];
                                return listEmpty
                            })
                        }}
                        textInputProps={
                            {
                                value: formatMoney(monthlyIncome) || '',
                                onChangeText: () => { },
                                placeholder: ''
                            }
                        }
                        format={'money'}
                        validate={(value) => validator.validateCurrency(value, null, null)}
                    />
                    <BottomSheetBranch title={t('screen_confirm.introduce_info.label_input_branch')}
                        data={branchList} show={showBottomSheetListBranch}
                        selected={branchId} label='tesst' labelSubmit='test'
                        onSubmit={(value) => {
                            handleSelectBranch(value)
                            setListEmpty(() => {
                                delete listEmpty['branchId'];
                                return listEmpty
                            })
                        }}
                        onClose={() => { setShowBottomSheetListBranch(false) }}
                    />
                    <BottomSheetSlider title={t('screen_confirm.loan_info.label_input_loan_term')} show={showBottomSheetSliderLoanTerm}
                        onClose={() => setShowBottomSheetSliderLoanTerm(false)}
                        min={Number(cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanTerm?.[0]?.loan_term_min)}
                        max={Number(cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanTerm?.[0]?.loan_term_max)}
                        value={Number(loanTerm) || Number(cmsLoanRegisterConfig?.data?.attributes?.DL_LoanRegister_LoanTerm?.[0]?.loan_term_default)}
                        onSubmit={(value) => { handleUpdateLoanDemandData({ loanTerm: String(value) }) }}
                    />
                    <BottomSheetInputNameAndDob
                        show={showBottomSheetInputNameAndDob}
                        title={t('screen_confirm.customer_info.name')}
                        label={t('screen_confirm.customer_info.label_input_name')}
                        labelSubmit={t('screen_confirm.customer_info.label_submit')}
                        textInputProps={
                            {
                                value: clientInfo?.data.clientName || '',
                                onChangeText: () => { },
                                placeholder: ''
                            }
                        }
                        onClose={() => { setShowBottomSheetInputNameAndDob(false) }}
                        onSubmit={(value) => { setShowBottomSheetInputNameAndDob(false); handleUpdateLoanDemandData({ clientName: value }) }}
                    />
                </View>
            </SafeAreaView>
        </ImageBackground>
    );
};

