import React, { useEffect, useRef, useState } from 'react';
import { View } from 'react-native';
import { useTheme, BottomSheetManager, BottomSheet, BottomSheetRef } from '@core/ui';
// import useStyles from './styles';
import { ScrollView } from 'react-native-gesture-handler';
import useCSS from '@src/presentation/style';
import MonthSlider from '../slider/MonthSlider';

interface BottomSheetInputProps {
    onSubmit?: (value: number) => void;
    show: boolean;
    title: string;
    onClose?: () => void;
    min: number;
    max: number;
    value: number;
}

const BottomSheetSlider = (props: BottomSheetInputProps) => {
    const { theme } = useTheme();
    const css = useCSS();
    const { onSubmit, title, show, onClose, min, max, value } = props;
    const bsRef = useRef<BottomSheetRef>(null);
    const [displayValue, setDisplayValue] = useState(value);

    const handleSubmit = (value: number) => {
        onSubmit?.(value);
        bsRef.current?.close();
    };
    const onShowModal = () => {
        BottomSheetManager.show({
            render: (portalId) => (
                <BottomSheet ref={bsRef} id={portalId} title={title} description='' onClose={onClose} enableContentPanningGesture={false}>
                    <ScrollView>
                        <MonthSlider min={min} max={max} value={value} onSubmit={handleSubmit} />
                    </ScrollView>
                </BottomSheet>
            ),
        });
    };

    useEffect(() => {
        if (show) {
            onShowModal();
        }
    }, [show]);
    return (
        <View></View>
    );
};

export default BottomSheetSlider;
