import { GetProductStatusHandler } from '@src/application/loan_product/queries/get_product_status/get_product_status_handler';
import { ProductStatusPayload } from '@src/application/loan_product/queries/get_product_status/get_product_status_query';

export const fetchGetInitLoanProposal = createAsyncThunk('get_init_loan_proposal/fetch', async (request: GetInitLoanProposalPayload) => {
    const getInitLoanProposal = container.get<GetInitLoanProposalHandler>(TYPES.GetInitLoanProposalHandler);
    return await getInitLoanProposal.handle(request);
});

